import SwiftUI
import WidgetKit

// SwiftUI for the three widgets (me-money NTF-08 small plant, NTF-09 medium pet and today,
// NTF-10 large plan). Every visible string comes prepared in the payload (EN or HI, picked in
// the app), except the placeholder, which comes from WidgetCatalog (generated by the config
// plugin from @smriti/i18n). Colours come from WidgetTheme (generated from tokens.json).
// No icons: the words carry the meaning, and the art is the seed-pack illustrations.

enum WidgetText {
  /// The device language, for the gallery and the placeholder (no payload to read it from).
  static var deviceLocale: String {
    Locale.preferredLanguages.first?.hasPrefix("hi") == true ? "hi" : "en"
  }

  static func string(_ key: String, locale: String = deviceLocale) -> String {
    WidgetCatalog.strings[locale]?[key] ?? WidgetCatalog.strings["en"]?[key] ?? ""
  }
}

extension View {
  /// iOS 17 asks for a container background; iOS 16.4 takes a plain one.
  @ViewBuilder
  func smritiWidgetBackground() -> some View {
    if #available(iOSApplicationExtension 17.0, *) {
      containerBackground(WidgetTheme.surface, for: .widget)
    } else {
      padding().background(WidgetTheme.surface)
    }
  }
}

struct ArtView: View {
  let name: String
  let locale: String
  var maxPoints: CGFloat = 160

  var body: some View {
    if let image = WidgetArt.image(name, maxPoints: maxPoints) {
      Image(uiImage: image)
        .resizable()
        .scaledToFit()
        .accessibilityLabel(Text(WidgetArt.alt(name, locale: locale)))
    } else {
      Color.clear.accessibilityHidden(true)
    }
  }
}

struct PlaceholderView: View {
  var body: some View {
    VStack(spacing: 8) {
      ArtView(name: "plant-seed", locale: WidgetText.deviceLocale, maxPoints: 80)
      Text(WidgetText.string("placeholder"))
        .font(.footnote.weight(.semibold))
        .foregroundColor(WidgetTheme.ink)
        .multilineTextAlignment(.center)
        .minimumScaleFactor(0.8)
    }
    .widgetURL(nil)
  }
}

/// The streak number and the plant line, shared by all three sizes.
struct PlantBlock: View {
  let payload: WidgetPayload
  let view: WidgetView

  var body: some View {
    VStack(alignment: .leading, spacing: 4) {
      ArtView(name: view.plantImage, locale: payload.snapshot.locale, maxPoints: 90)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
      Text(payload.text.streak)
        .font(.headline)
        .foregroundColor(WidgetTheme.streakText)
        .lineLimit(1)
        .minimumScaleFactor(0.7)
      Text(view.lineText)
        .font(.caption)
        .foregroundColor(view.goalMet ? WidgetTheme.successText : WidgetTheme.inkMuted)
        .lineLimit(2)
        .minimumScaleFactor(0.8)
    }
  }
}

struct PlantWidgetView: View {
  let entry: SmritiEntry

  var body: some View {
    if let p = entry.payload {
      let v = WidgetRules.view(p, now: entry.date)
      PlantBlock(payload: p, view: v)
        .widgetURL(URL(string: v.lineLink))
    } else {
      PlaceholderView()
    }
  }
}

struct PillView: View {
  let text: String
  let link: String

  var body: some View {
    if let url = URL(string: link) {
      Link(destination: url) {
        Text(text)
          .font(.caption.weight(.semibold))
          .foregroundColor(WidgetTheme.onAccent)
          .lineLimit(1)
          .minimumScaleFactor(0.8)
          .padding(.horizontal, 12)
          .padding(.vertical, 6)
          .background(Capsule().fill(WidgetTheme.accent))
      }
    }
  }
}

struct TodayWidgetView: View {
  let entry: SmritiEntry

  var body: some View {
    if let p = entry.payload {
      let v = WidgetRules.view(p, now: entry.date)
      HStack(spacing: 12) {
        PlantBlock(payload: p, view: v)
          .frame(maxWidth: .infinity)
        VStack(alignment: .leading, spacing: 6) {
          if let pet = p.images.pet, let url = URL(string: p.links.pet) {
            Link(destination: url) {
              HStack(spacing: 6) {
                ArtView(name: pet, locale: p.snapshot.locale, maxPoints: 48)
                  .frame(width: 44, height: 44)
                if let label = p.text.petLabel {
                  Text(label)
                    .font(.caption)
                    .foregroundColor(WidgetTheme.ink)
                    .lineLimit(2)
                }
              }
            }
          }
          if let progress = v.progressText {
            Text(progress)
              .font(.subheadline.weight(.semibold))
              .foregroundColor(v.goalMet ? WidgetTheme.successText : WidgetTheme.ink)
              .lineLimit(1)
            ProgressView(value: min(1, max(0, v.progress)))
              .tint(v.goalMet ? WidgetTheme.success : WidgetTheme.accent)
              .accessibilityHidden(true)
          }
          Spacer(minLength: 0)
          PillView(text: v.pillText, link: v.pillLink)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
      }
      .widgetURL(URL(string: v.lineLink))
    } else {
      PlaceholderView()
    }
  }
}

struct PlanWidgetView: View {
  let entry: SmritiEntry

  var body: some View {
    if let p = entry.payload {
      let v = WidgetRules.view(p, now: entry.date)
      VStack(alignment: .leading, spacing: 10) {
        HStack(alignment: .top, spacing: 12) {
          PlantBlock(payload: p, view: v)
            .frame(width: 120, height: 140)
          VStack(alignment: .leading, spacing: 6) {
            if let countdown = v.countdown {
              Text(countdown)
                .font(.headline)
                .foregroundColor(WidgetTheme.ink)
                .lineLimit(2)
            }
            if let progress = v.progressText {
              Text(progress)
                .font(.subheadline)
                .foregroundColor(v.goalMet ? WidgetTheme.successText : WidgetTheme.inkMuted)
            }
          }
          Spacer(minLength: 0)
        }
        Divider().overlay(WidgetTheme.line)
        HStack {
          Text(v.planHeader)
            .font(.subheadline.weight(.semibold))
            .foregroundColor(WidgetTheme.ink)
          Spacer()
          if v.planDone {
            Text(p.text.done)
              .font(.caption.weight(.semibold))
              .foregroundColor(WidgetTheme.successText)
          }
        }
        ForEach(Array(v.planRows.enumerated()), id: \.offset) { _, row in
          if let url = URL(string: row.link) {
            Link(destination: url) {
              Text(row.text)
                .font(.subheadline)
                .foregroundColor(WidgetTheme.ink)
                .lineLimit(1)
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.vertical, 8)
                .padding(.horizontal, 10)
                .background(RoundedRectangle(cornerRadius: 10).fill(WidgetTheme.surfaceSunken))
            }
          }
        }
        Spacer(minLength: 0)
        PillView(text: v.pillText, link: v.pillLink)
      }
      .widgetURL(URL(string: p.links.plan))
    } else {
      PlaceholderView()
    }
  }
}
